import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.CWgsre3x.js";const b=JSON.parse('{"title":"Τοπικά προσχέδια και ανάκτηση","description":"","frontmatter":{},"headers":[],"relativePath":"el/websites/draft-storage.md","filePath":"el/websites/draft-storage.md"}'),l={name:"el/websites/draft-storage.md"};function i(s,a,n,d,h,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="τοπικα-προσχεδια-και-ανακτηση" tabindex="-1">Τοπικά προσχέδια και ανάκτηση <a class="header-anchor" href="#τοπικα-προσχεδια-και-ανακτηση" aria-label="Permalink to &quot;Τοπικά προσχέδια και ανάκτηση&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς — προσχέδιο βάσει κώδικα</p><p>TransferBook+ v0.7.9. Η διαθεσιμότητα εξαρτάται από την εγκατεστημένη έκδοση, τα δικαιώματα και τις ρυθμίσεις. Ο οδηγός δεν επιβεβαιώνει δημόσια δημοσίευση.</p></div><h2 id="σκοπος" tabindex="-1">Σκοπός <a class="header-anchor" href="#σκοπος" aria-label="Permalink to &quot;Σκοπός&quot;">​</a></h2><p>Διατηρήστε την εργασία πριν αλλάξετε εταιρεία, browser, συσκευή ή τρόπο λειτουργίας. Στην έκδοση αναφοράς το Website Studio αποθηκεύει τοπικά ανά εταιρεία και τρόπο λειτουργίας.</p><h2 id="αποθηκευση-και-ανακτηση" tabindex="-1">Αποθήκευση και ανάκτηση <a class="header-anchor" href="#αποθηκευση-και-ανακτηση" aria-label="Permalink to &quot;Αποθήκευση και ανάκτηση&quot;">​</a></h2><ol><li>Επιβεβαιώστε εταιρικό περιβάλλον και επιλεγμένη ιστοσελίδα.</li><li>Αποθηκεύστε με τα διαθέσιμα εργαλεία και ελέγξτε το αποτέλεσμα.</li><li>Εξαγάγετε φορητό πακέτο ιστοσελίδας και διατηρήστε ανεξάρτητο αντίγραφο.</li><li>Στο History εξετάστε προηγούμενα τοπικά στιγμιότυπα και επαναφέρετε κατάλληλη αναθεώρηση όταν χρειάζεται.</li><li>Πριν αλλάξετε browser ή τρόπο λειτουργίας, εξαγάγετε πρώτα. Εισαγάγετε στον σωστό εξουσιοδοτημένο χώρο και επικυρώστε ξανά.</li></ol><h2 id="αναμενομενο-αποτελεσμα" tabindex="-1">Αναμενόμενο αποτέλεσμα <a class="header-anchor" href="#αναμενομενο-αποτελεσμα" aria-label="Permalink to &quot;Αναμενόμενο αποτέλεσμα&quot;">​</a></h2><p>Το προσχέδιο παραμένει τοπικό στον browser και στο αντίστοιχο περιβάλλον. Η τοπική αποθήκευση δεν είναι κρυπτογράφηση, αντίγραφο ασφαλείας server ή συγχρονισμός συσκευών.</p><h2 id="αντιμετωπιση-προβληματων" tabindex="-1">Αντιμετώπιση προβλημάτων <a class="header-anchor" href="#αντιμετωπιση-προβληματων" aria-label="Permalink to &quot;Αντιμετώπιση προβλημάτων&quot;">​</a></h2><p>Αν η αποθήκευση δεν είναι διαθέσιμη, θεωρήστε ότι απέτυχε και εξαγάγετε όπου είναι δυνατόν πριν κλείσετε. Παλαιότερα προσχέδια χωρίς εταιρική αντιστοίχιση δεν μεταφέρονται αυτόματα. Χρησιμοποιήστε εξαγωγή/εισαγωγή από το αρχικό περιβάλλον, όχι αντιγραφή κλειδιών αποθήκευσης. Δείτε <a href="./portable-packages.html">φορητά πακέτα</a>.</p><h2 id="αυτοματη-αποθηκευση-και-αντιγραφα-χωρου-εργασιας-στη-v0-7-10" tabindex="-1">Αυτόματη αποθήκευση και αντίγραφα χώρου εργασίας στη v0.7.10 <a class="header-anchor" href="#αυτοματη-αποθηκευση-και-αντιγραφα-χωρου-εργασιας-στη-v0-7-10" aria-label="Permalink to &quot;Αυτόματη αποθήκευση και αντίγραφα χώρου εργασίας στη v0.7.10&quot;">​</a></h2><p><strong>Κατάσταση: έκδοση staging ελεγμένη βάσει κώδικα.</strong> Η αυτόματη αποθήκευση και η ανάκτηση είναι απομονωμένες ανά εταιρεία και τρόπο λειτουργίας, όπως τα αποθηκευμένα προσχέδια. Η αυτόματη αποθήκευση δεν αντικαθιστά τον κύριο αποθηκευμένο χώρο.</p><ol><li>Αν η ειδοποίηση ανάκτησης προσφέρει μη αποθηκευμένο προσχέδιο, ελέγξτε την ιστοσελίδα και τον χρόνο ανάκτησης. Επαναφέρετε μόνο το σωστό προσχέδιο, επιλέξτε Save Draft και επιβεβαιώστε το αποτέλεσμα.</li><li>Στο History ελέγξτε τη χρήση αποθηκευτικού χώρου και την επικύρωση. Εξαγάγετε πλήρες αντίγραφο χώρου εργασίας (<code>.json</code>) για ανεξάρτητη φύλαξη, επιπλέον των φορητών πακέτων ιστοσελίδας.</li><li>Για επαναφορά πλήρους αντιγράφου χρησιμοποιήστε τη συμβατή εισαγωγή στο εξουσιοδοτημένο περιβάλλον. Ελέγξτε τις ανακτημένες ιστοσελίδες πριν αποθηκεύσετε. Μην παρακάμπτετε περιορισμούς μεταξύ εταιρειών.</li><li>Αν εμφανιστεί ειδοποίηση εξάντλησης χώρου ή αλλοιωμένων δεδομένων, διατηρήστε διαθέσιμα αντίγραφα πριν από εκκαθάριση. Το ιστορικό αναθεωρήσεων μπορεί να περιοριστεί λόγω έλλειψης χώρου· μην θεωρείτε δεδομένη τη διατήρηση όλων των εκδόσεων.</li></ol><p>Η ανάκτηση browser δεν αποτελεί αντίγραφο server ή συγχρονισμό συσκευών.</p><h2 id="αλλαγες-που-περιγραφονται-στις-v0-7-12–v0-7-14" tabindex="-1">Αλλαγές που περιγράφονται στις v0.7.12–v0.7.14 <a class="header-anchor" href="#αλλαγες-που-περιγραφονται-στις-v0-7-12–v0-7-14" aria-label="Permalink to &quot;Αλλαγές που περιγράφονται στις v0.7.12–v0.7.14&quot;">​</a></h2><p>Η v0.7.12 προσθέτει εξουσιοδοτημένη προετοιμασία μεγαλύτερων αιτημάτων σχεδιασμού, η v0.7.13 ενσωματώνει Website Studio και Template Manager και η v0.7.14 περιγράφει βελτιώσεις προσχεδίων και αναθεωρήσεων στον διακομιστή. Οι καταγραφές συμπληρώνουν τις ιστορικές διαδικασίες τοπικής αποθήκευσης. Επιβεβαιώστε τον πραγματικό τρόπο αποθήκευσης, το αποτέλεσμα, τη διαθεσιμότητα αναθεωρήσεων, την εταιρεία και τη μέθοδο ανάκτησης. Η προετοιμασία ή αποθήκευση δεν εξουσιοδοτεί δημόσια δημοσίευση. Διατηρήστε φορητό αντίγραφο ασφαλείας όπου χρειάζεται.</p><p>Δείτε <a href="/el/release-notes/">Σημειώσεις εκδόσεων</a>.</p>',17)])])}const f=e(l,[["render",i]]);export{b as __pageData,f as default};
